for p in frame['SOURCE_IDENTITIES']:codec.validate_pin(codec._unwire(p));codec.load_pinned(R,codec._unwire(p))
sp=R/frame['PROVENANCE']['SNAPSHOT_SOURCE']['path'];snap=codec.decode_snapshot(sp.read_bytes());model.validate_model(snap);assert codec._wire(codec.snapshot_id(snap))==frame['CHECKPOINT_STATE']
origplan=R/'docs/plans/DETERMINISTIC_PLANNER_V0_1_CANONICAL_QUALIFICATION_EXPERIMENT_1.md';assert 'exact admitted identity/version' in origplan.read_text() and 'No `import_e1`' in origplan.read_text()
