rows=[];configs={}
for version in ['E1-SELECTION-1-P05','E1-SELECTION-1-P06']:
 b=selector.validate_policy(selector.POLICY_PIN,version);raw=codec.load_pinned(R,b.artifact);config=json.loads(selector.policy_contract_bytes(b));digest=sha(selector.policy_contract_bytes(b));assert digest==selector.CONTRACT_DIGESTS[version]
