comparison={'P05_P06_RELATIONSHIP':'SAME_POLICY_DIFFERENT_VERSION','FIELDS_DIFFERING':['version'],'SELECTOR_ALGORITHM_EQUAL':True,'SOURCE_BYTES_EQUAL':True,'CONTENT_IDENTITY_EQUAL':True,'CONFIGURATION_IDENTITY_EQUAL':False,'GENERATION_SCOPE_LINEAGE_FIELDS':'Not policy-owned fields; applicability belongs to exact frame/bundle context','CONSUMER_EQUAL_FOR_FRAME':True,'REPLAY_EFFECT':'Both accept this zero-event external/decision state; FULL_FROZEN_E1_REPLAY requires P06 and cannot be inferred from choosing P06. Policy/version must be separately fixed before native scope binding.','BUNDLE_IDENTITY_EFFECT':'Canonical bundle and resume-binding envelopes include policy_version. Different declared version changes identity-bearing bytes and expected bundle/trusted input commitments; no bundle ID computed here.','D01_OBLIGATION_EFFECT':'Algorithm/requirements not waived or changed by version; full native output/manifest identities differ with binding. Frozen 128 obligations remain intact and their version-specific expected outputs must later be sealed.','MUTATION_INVALIDATION_EFFECT':'Native handlers are unchanged for frame; no empirical D01 mutation/invalidation execution or generic future equivalence claimed','COLD_READER_EFFECT':'Same checkpoint Snapshot expected for same range/scope; bundle policy/version and trusted bundle identity must match chosen version exactly','END_ASSURANCE_EFFECT':'Choice proves neither E1 import nor E2 phase execution; no END binding or historical reconstruction follows','CHOICE_IS_PRESENTATION_ONLY':False}
save('p05-p06-comparison.json',comparison)
selection={'POLICY_BINDING_UNIQUE':False,'POLICY_SELECTION_RULE':None,'RULE_SEARCH_RESULTS':{'checkpoint_generation':'No mapping from E2-GENERATION-1 to registry version','lineage':'No mapping from E2-CANONICAL-BASELINE-1 to policy_version','history_frame':'Subject explicitly excluded policy/version selection','runner_phase':'A14 V2 expects bundle field, no importer/default selection','END_phase':'No scope import authorizes choosing version','currentness':'Exact reviewed binding validation required; no latest-version rule','generic_fixture':'P05 generic fixture example is not the exact A14 input binding'},'COMPATIBILITY_MEANING':'Both are technically legitimate native choices for this frame; final qualification ownership must select exactly one, not merely show compatibility','AMBIGUITY_CLASSIFICATION':'QUALIFICATION_SCOPE_CHOICE','UNDERLYING_GAP':'Exact prospective A14 runner/bundle version binding absent from recovered contract; no historical binding can be recovered from a deliberately new zero-event frame','EXISTING_AUTHORITY_PERMITS_SELECTION':False,'SELECTED_POLICY':None}
save('selection-rule-and-authority.json',selection)
range={'REPLAY_START':frame['CHECKPOINT_STATE'],'REPLAY_END':frame['CHECKPOINT_STATE'],'EVENT_SET':[],'FRAME_IDENTITY':packet['FRAME_IDENTITY'],'CHECKPOINT':frame['PROVENANCE']['SNAPSHOT_SOURCE'],'SOURCE_SET':frame['SOURCE_IDENTITIES'],'SCOPE':frame['SCOPE'],'LINEAGE':frame['LINEAGE'],'GENERATION':frame['GENERATION'],'PROVENANCE':frame['PROVENANCE']}
scopeprep={'REPLAY_RANGE':range,'REPRESENTATION':'Future native PersistenceBundle.initial/current/events/sources/policy/policy_version/scope; exact native identity requires complete selected fields. Metadata preparation is not a bundle or candidate-specific replay binding.','POLICY_BOUND_FIELD':'Exact one candidate from current inventory must be selected first','SCOPE_BOUND_FIELD':'Native replay scope separately bound to selected policy and qualification assurance, not Snapshot scope string','NATIVE_SCOPE_CONSTRAINTS':{'PARTIAL_HISTORICAL_REPLAY':'Supported with P05/P06; local zero range entails source/policy/model/exact Snapshot validation','FULL_FROZEN_E1_REPLAY':'Native requires P06; canonical E2 excludes import_e1, selecting P06 does not authorize this mode','PARTIAL_SYNTHETIC_BUDGET_QUALIFICATION':'Native enum; no A14 budget-scope mapping established'},'EXPECTED_RECONSTRUCTION':'No event applications; validate exact selected policy/source/provenance/schema and retain exact checkpoint identity','FORBIDDEN_EXECUTION':['A14/D01','save/restore/commit','live import_e1','new Evidence/receipt/authority/INSTALL'],'REPLAY_SCOPE_SELECTED':False,'CANDIDATE_SPECIFIC_BINDING_SEALED':False}
save('replay-scope-binding-preparation.json',scopeprep)
