for row in rows:
 suffix=row['VERSION'].split('-')[-1];name='AUTHORIZE_BOUNDED_A14_POLICY_BINDING_E1_SELECTION_1_'+suffix
 options.append({'OPTION':name,'SELECTED_POLICY_IF_AUTHORIZED':row,'FRAME_IDENTITY':packet['FRAME_IDENTITY'],'REPLAY_RANGE':range,'REPLAY_SCOPE_EFFECT':'Constrain future replay validation to exact selected policy/version; scope remains unselected and requires separate native assurance binding. No E1 import authorized.','D01_QUALIFICATION_EFFECT':'One reviewed version for prospective A14 case inputs and later full-output identities; does not execute/requalify or drop obligations','HISTORICAL_CLAIM_EFFECT':'Prospective version binding only; no original D01 matrix/historical lineage reconstruction','BUNDLE_IDENTITY_EFFECT':'Exact policy_version becomes part of future native bundle/resume identity bytes; no bundle constructed now','EXCLUDED_CLAIMS':['No policy source/rule/config drift or new policy admission','No reinterpretation as E2-P05/P06 phase authorization','No replay-scope selection, E1 import or real-world proof','No A14/D01/P05/P06 execution, save/read, bundle creation, INSTALL or authority issuance','No automatic operand promotion or END binding']})
